              {categories.map(category => (
                <tr>
                  <th scope="row">{categoryLabelFor(category)}</th>
                  {series.map(item => {
                    const datum = valueFor(item, category)

                    return (
                      <td>
                        {datum?.label ??
                          (datum?.y === null || datum === undefined ?
                            'Not available' :
                            formatValue(datum.y))}
                      </td>
                    )
                  })}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </details>
    )
  }
</Chart>

