export interface PasswordFieldProps extends Omit<
  InputProps,
  'type' | 'visualSize'
> {
  error?: ReactNode
  hideLabel?: string
  hint?: ReactNode
  label?: ReactNode
  showLabel?: string
}

export const PasswordField = ({
  'aria-describedby': ariaDescribedby,
  className,
  error,
  hideLabel = 'Hide password',
  hint,
  id,
  label = 'Password',
  name,
  ref,
  showLabel = 'Show password',
  ...props
}: PasswordFieldProps) => {
  const generatedId = useId()
  const controlId = id ?? `ui-password-${generatedId}`
  const hintId = hint ? `${controlId}-hint` : undefined
  const errorId = `${controlId}-error`

  const describedBy = getPasswordFieldDescribedBy(
    ariaDescribedby, hintId, error ? errorId : undefined
  )

  const inputRef = useRef<HTMLInputElement | null>(null)
  const { toggleVisibility, visible } = usePasswordVisibility(inputRef)

  return (
    <Field
      className={composeClassName('ui-password-field', className)}
      controlId={controlId}
      invalid={Boolean(error)}
      {...(describedBy ? { describedBy } : {})}
    >
      <Label htmlFor={controlId}>{label}</Label>
      <PasswordFieldControl
        controlId={controlId}
        describedBy={describedBy}
        error={error}
        forwardedRef={ref}
        hideLabel={hideLabel}
        inputProps={props}
        inputRef={inputRef}
        name={name}
        showLabel={showLabel}
        toggleVisibility={toggleVisibility}
        visible={visible}
      />
      <PasswordFieldMessages
        error={error}
        errorId={errorId}
        hint={hint}
        hintId={hintId}
      />
    </Field>
  )
}

