import { Select } from '@santi020k/lumen-react'
import { useSelect } from '@santi020k/lumen-react'

export function CountrySelect() {
  const select = useSelect({
    options: ['United States', 'Canada', 'Mexico'],
    placeholder: 'Choose a country',
    onValueChange: (value) => console.log('Selected:', value)
  })

  return (
    <div {...select.rootProps}>
      <button {...select.triggerProps}>{select.triggerText}</button>
      <select {...select.nativeSelectProps} />
      <div {...select.listProps}>
        {select.options.map(option => (
          <button key={option.value} {...select.getOptionProps(option)}>
            {option.label}
          </button>
        ))}
      </div>
    </div>
  )
}

react.source:
export interface SelectProps
  extends
  Omit<
    NativeSelectProps,
    | 'defaultValue' |
    'disabled' |
    'id' |
    'name' |
    'onChange' |
    'options' |
    'placeholder' |
    'required' |
    'size' |
    'value'
  >,
  SelectOptions {
  glass?: LumenGlassProp
  inputRef?: Ref<HTMLSelectElement>
  onChange?: ComponentPropsWithoutRef<'select'>['onChange']
  size?: 'default' | 'lg' | 'md' | 'sm'
}

export const Select = ({
  children,
  className,
  defaultValue,
  disabled = false,
  glass = false,
  id,
  inputRef,
  name,
  onChange,
  onValueChange,
  options = emptyOptions,
  placeholder,
  required = false,
  size = 'default',
  value,
  ...props
}: SelectProps) => {
  const select = useSelect({
    defaultValue,
    disabled,
    id,
    name,
    onValueChange,
    options,
    placeholder,
    required,
    value
  })

  const sizeClass = getSelectSizeClass(size)

  return (
    <div
      {...select.rootProps}
      className={composeClassName(
        'ui-select-field', glassClass('ui-select-field', glass), className
      )}
      data-ui-glass-track={glass ? true : undefined}
    >
      <select
        {...select.nativeSelectProps}
        {...props}
        className={composeClassName('ui-select ui-select__native', sizeClass)}
        onChange={composeHandlers(onChange, select.nativeSelectProps.onChange)}
        ref={inputRef}
      >
        {placeholder && (
          <option data-ui-select-placeholder disabled value="">
            {placeholder}
          </option>
        )}
        {children}
        {select.options.map(option => (
          <option
            disabled={option.disabled}
            key={option.value}
            value={option.value}
          >
            {option.label}
          </option>
        ))}
      </select>

      <div {...select.controlProps} className="ui-select__control">
        <button
          {...select.triggerProps}
          className={composeClassName(
            'ui-select ui-select__trigger', sizeClass
          )}
          type={select.triggerProps.type ?? 'button'}
        >
          <span data-ui-select-value>{select.triggerText}</span>
        </button>

        <div {...select.listProps} className="ui-select__list">
          {select.options.map(option => {
            const optionProps = select.getOptionProps(option)

            return (
              <button
                key={option.value}
                {...optionProps}
                type={optionProps.type ?? 'button'}
              >
                {option.label}
              </button>
            )
          })}
        </div>
      </div>
    </div>
  )
}

