  label,
  value,
  variant = 'default',
  children,
  ...props
}: StatProps<T>) => (
  <Primitive
    {...(as ? { as } : {})}
    className={composeClassName(
      variant !== 'default' && `ui-stat--${variant}`, className
    )}
    data-slot="stat"
    data-variant={variant}
    {...props}
