export interface SegmentedProps extends Omit<
  ComponentPropsWithoutRef<'div'>,
  'onChange'
> {
  defaultValue?: string
  name?: string
  onValueChange?: (value: string) => void
  options?: SelectOption[]
  size?: 'default' | 'lg' | 'sm'
  value?: string
}

export const Segmented = ({
  children,
  className,
  defaultValue,
  name = 'segmented',
  onValueChange,
  options = emptyOptions,
  size = 'default',
  value = defaultValue,
  ...props
}: SegmentedProps) => (
