  opacity: number
  selected: boolean
}

export const resolveLumenNavigationItemState = (
  colors: LumenTheme['colors'],
  itemValue: string,
  selectedValue: string,
  disabled: boolean,
  pressed: boolean
): LumenNavigationItemState => {
  const selected = itemValue === selectedValue
  let opacity = 1

